import sailpoint.object.QueryOptions;
import sailpoint.object.Identity;

// Create query options based on the group filter (e.g., department = "Finance")
QueryOptions qo = new QueryOptions();
qo.addFilter(group.getFilter());

// Search for all members of the group
Iterator identities = context.search(Identity.class, qo);

Identity emp = null;
Identity owner = null;

while (identities.hasNext()) {
  emp = (Identity) identities.next();

  Object isManagerAttr = emp.getAttribute("isManager");

  // Check if the "isManager" attribute is set and equals true (boolean or string "true")
  if (isManagerAttr != null && (isManagerAttr.equals(Boolean.TRUE) || "true".equalsIgnoreCase(isManagerAttr.toString()))) {
    owner = emp;
    break;
  }
}

// If no manager was found, default to spadmin
if (owner == null) {
  log.debug("No manager found for group: " + group.getName() + ". Defaulting to spadmin.");
  return "spadmin";
}

log.debug("Assigned owner for group: " + group.getName() + " is: " + owner.getName());
return owner;
